import timefrom Sengo1 import *from mpython import *from machine import UARTuart1 = UART(1, baudrate=115200, tx=Pin.P14, rx=Pin.P13)sengo1 = Sengo1(0x60)# 自定义函数def UART():  global my_variable, key_N, key_P, key_T, key_H, key_A, key_B, start, index  sengo1.begin(uart1)def I2C():  global my_variable, key_N, key_P, key_T, key_H, key_A, key_B, start, index  sengo1.begin(i2c)def Display():  global my_variable, key_N, key_P, key_T, key_H, key_A, key_B, start, index  oled.fill_rect(0, (2-1)*16, 128, 16, 0)  oled.show()  # Sengo1不主动返回检测识别结果，需要主控板发送指令进行读取。读取的流程：首先读取识别结果的数量，接收到指令后，Sengo1会刷新结果数据，如果结果数量不为零，那么主控再发送指令读取结果的相关信息。请务必按此流程构建程序。  # Sengo最多输出1个识别结果。  if ((sengo1.GetValue(sengo1_vision_e.kVisionBody, sentry_obj_info_e.kStatus)) > 0):    if ((sengo1.GetValue(sengo1_vision_e.kVisionBody,sentry_obj_info_e.kHeightValue)) > 60):      oled.DispChar("Distrance: Near", 0, (2-1)*16, 1)    elif ((sengo1.GetValue(sengo1_vision_e.kVisionBody,sentry_obj_info_e.kHeightValue)) < 40):      oled.DispChar("Distance: Far", 0, (2-1)*16, 1)    else:      oled.DispChar("Distance: Middle", 0, (2-1)*16, 1)    oled.DispChar((str((sengo1.GetValue(sengo1_vision_e.kVisionBody,sentry_obj_info_e.kXValue)))), 32, 32, 1)    oled.DispChar((str((sengo1.GetValue(sengo1_vision_e.kVisionBody,sentry_obj_info_e.kYValue)))), 96, 32, 1)    oled.DispChar((str((sengo1.GetValue(sengo1_vision_e.kVisionBody,sentry_obj_info_e.kWidthValue)))), 32, 48, 1)    oled.DispChar((str((sengo1.GetValue(sengo1_vision_e.kVisionBody,sentry_obj_info_e.kHeightValue)))), 96, 48, 1)  else:    oled.fill_rect(32,32,32,16,0)    oled.fill_rect(96,32,32,16,0)    oled.fill_rect(32,48,32,16,0)    oled.fill_rect(96,48,32,16,0)  oled.show()start = 0# 等待Sengo1完成初始化，此延时不可以去掉，避免Sengo1初始化尚未完成，主控板已经发送指令time.sleep(2)oled.DispChar("Algo: Body", 0, 0, 1)oled.DispChar("x=", 0, 32, 1)oled.DispChar("y=", 64, 32, 1)oled.DispChar("w=", 0, 48, 1)oled.DispChar("h=", 64, 48, 1)oled.show()I2C()# 1、参考文档# https://tosee.readthedocs.io/zh/latest/Sentry1/Vision/index.html#chapter-vs1-vision-body-index# 2、参考视频（注：Sengo1与Sentry1是两款产品）# https://www.bilibili.com/video/BV1S84y137if/?spm_id_from=333.1387.upload.video_card.click&vd_source=a6a4a13d17ed26ee248472534a8ec3cc# 3、人体检测算法常见应用：门禁闸机；人体跟踪云台# 4、应用案例：人体跟踪云台# https://www.bilibili.com/video/BV1oo4y1H7Tb/?spm_id_from=333.1387.upload.video_card.click&vd_source=a6a4a13d17ed26ee248472534a8ec3cc# 5、Sengo1每次只能运行一种识别算法；sengo1.VisionBegin(sengo1_vision_e.kVisionBody)while True:  Display()